{
  "probability": 0.97,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "As of February 2026, around 606 Mediterranean deaths/missing, suggesting a high pace heading into March–May.",
    "Historical annual Mediterranean death totals typically run around 2,100–2,452, making a 1,000-death-by-May threshold plausible if the pace continues.",
    "Uncertainties include weather conditions, SAR capacity/policy changes, and reporting lags, which could push totals up or down.",
    "Bayesian calibration yields a posterior probability of 97% that the Missing Migrants Project records at least 1,000 Mediterranean deaths before May 2026."
  ],
  "confidence": "high",
  "narrative": "Early-2026 pace suggests a strong likelihood of surpassing 1,000 Mediterranean deaths by May 2026, anchored by historical totals; updates from pace and baseline support a high posterior probability, though weather and reporting gaps introduce uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "Reference class: Central Mediterranean route fatalities per calendar year as tracked by IOM Missing Migrants Project; early-2026 counts and historical baselines justify a high anchor around 0.85."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "As of February 2026, about 606 deaths/missing; if the pace persists into March–May, the threshold of 1,000 by May becomes plausible."
      },
      {
        "factor": "Historical annual Mediterranean toll context (approx. 2,100–2,452 per year)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Past years show totals well above 1,000; a high early-year pace is a reasonable signal for hitting the threshold by May."
      },
      {
        "factor": "Weather and storms increasing fatality risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Persistent rough seas raise crossing risk and fatalities, nudging totals upward."
      },
      {
        "factor": "Data reporting lag and potential revisions to IOM counts",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Unverified missing cases and reporting delays could understate observed counts; this tempers the trajectory slightly."
      }
    ],
    "synthesis_rationale": "The final posterior combines a strong up-weight from the early-2026 pace with a robust baseline of historical fatalities; small down-ticks from reporting lags are applied to calibrate, yielding a high-probability forecast close to 0.97 with a narrow credible interval. Calibration acknowledges substantial uncertainty from weather, SAR policy, and data revisions."
  }
}

{
  "probability": 0.97,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "As of February 2026, about 606 Mediterranean deaths have been recorded, implying a pace that could push the total past 1,000 by May if sustained.",
    "Historical baselines (roughly 2,100–2,452 deaths per year) make crossing 1,000 by May plausible under a continued high pace.",
    "Downside factors include potential SAR capacity improvements and weather that could reduce risk, plus reporting gaps that may understate counts.",
    "Overall, evidence supports a very high likelihood of reaching at least 1,000 Mediterranean deaths before May 2026, with calibrated uncertainty."
  ],
  "confidence": "high",
  "narrative": "Early-2026 counts indicate a deadly start to the year. If the February pace persists through March–April, reaching 1,000 Mediterranean deaths by May is highly plausible, though weather, SAR capacity, and reporting lags introduce some uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class of Central Mediterranean fatalities per calendar year; historical annual tolls (~2,100–2,452) combined with the observed early-2026 pace suggest a mid-to-high starting point before updates."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "As of February 2026, ~606 deaths/missing; if that pace continues into March–April, total could exceed 1,000 by May."
      },
      {
        "factor": "Weather and storms increasing fatality risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "January storms and rough seas have elevated risk; persistent poor seas would push counts higher."
      },
      {
        "factor": "Search-and-rescue policy environment and capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Policy shifts and funding constraints may reduce rescues, elevating fatalities and the trajectory toward 1,000."
      },
      {
        "factor": "Data reporting lag and potential revisions to IOM Missing Migrants counts",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Underreporting or delays could mean observed counts are understating the toll, partially offsetting upward updates."
      },
      {
        "factor": "Seasonal/weather conditions March–May 2026",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved spring conditions could reduce crossings and fatalities, potentially dampening the trajectory."
      }
    ],
    "synthesis_rationale": "The posterior of 0.97 reflects strong upward pressure from the early-2026 pace and historical context, tempered by modest downward pressures from seasonal improvement and potential reporting gaps. The updates collectively place the probability in a high range, with a narrow calibrated band around 0.92–0.99 to reflect remaining uncertainty about weather, SAR, and data revisions."
  }
}

{
  "probability": 0.72,
  "range_low": 0.60,
  "range_high": 0.84,
  "summary": [
    "Early-2026 data show about 606 Mediterranean deaths by late February, indicating a pace above neutral year-to-date expectations.",
    "If that pace persists through March–April, reaching 1,000 deaths by May is plausible given historical annual totals around 2,100–2,452.",
    "Key uncertainties include weather conditions, search-and-rescue capacity/policy changes, and reporting gaps, plus potential shifts to Atlantic/Canary routes that could dampen or amplify the central Mediterranean tally.",
    "Calibrated forecast: probability 0.72 with a 0.60–0.84 uncertainty band and moderate confidence."
  ],
  "confidence": "medium",
  "narrative": "With ~606 deaths by February, the near-term pace supports a plausible path to 1,000 by May, but substantial uncertainty remains from weather, SAR policy, and data gaps. The final estimate weights early-2026 momentum against potential dampening factors, yielding a calibrated probability around 0.72 (range 0.60–0.84).",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class is annual Central Mediterranean fatalities as tracked by IOM Missing Migrants Project; historical totals ~2,100–2,452 per year. 1,000 by May represents roughly the first half of a typical toll; early 2026 counts (606 by February) imply a non-trivial chance that pace persists into spring, justifying a mid-range anchor around 0.65."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February suggest a pace significantly above neutral; if March–April–May continue similarly, the 1,000-death threshold by May becomes plausible, lifting the probability."
      },
      {
        "factor": "Weather and storms increasing fatality risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Continued rough seas and winter storm activity raise crossing risk, increasing near-term mortality potential."
      },
      {
        "factor": "Search-and-rescue capacity/policy environment",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Policy constraints and limited rescue capacity can elevate fatalities; persistent constraints would push counts higher."
      },
      {
        "factor": "Data reporting gaps and missing cases",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "IOM Missing Migrants data often involve lags and revisions; if gaps persist, observed counts by May may understate true toll, nudging the trajectory upward."
      },
      {
        "factor": "Shifts to Atlantic/Canary Islands route",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "If more migrants move to alternative routes, central Mediterranean fatalities could be lower, exerting downward pressure on the observed toll."
      },
      {
        "factor": "Mass casualty risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A single large shipwreck could disproportionately raise counts in a short window, moving the total toward the threshold."
      }
    ],
    "synthesis_rationale": "Starting from a balanced anchor around 0.65, the strongest drivers (early-2026 pace and mass casualty risk) push the estimate upward toward ~0.72. Downward pressures (route shifts, potential weather improvements) and data gaps introduce uncertainty, yielding a calibrated range of 0.60–0.84. Calibration reflects the volatility of near-term maritime fatalities and reporting lags while anchoring to historical annual scales."
  }
}
